m\" type=\"submit\">\n                        {c('Feature').ngettext(\n                            msgid`Add (${numberOfAddedServers})`,\n                            `Add (${numberOfAddedServers})`,\n                            numberOfAddedServers\n                        )}\n                    </Button>\n                ) : (\n                    <Button color=\"norm\" type=\"submit\" disabled>\n                        {c('Feature').t`Add`}\n                    </Button>\n                )}\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default GatewayAddServersModal;\n","import React, { useState } from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Cell,\n    Form,\n    Icon,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    Table,\n    TableBody,\n    TableCell,\n    TableRow,\n    useModalTwoStatic,\n} from '@proton/components/components';\nimport { MAX_IPS_ADDON } from '@proton/shared/lib/constants';\nimport range from '@proton/utils/range';\n\nimport { Gateway } from './Gateway';\nimport GatewayAddServersModal from './GatewayAddServersModal';\nimport { GatewayLogical } from './GatewayLogical';\nimport { GatewayUser } from './GatewayUser';\nimport { getCountryFlagAndName } from './getCountryFlagAndName';\nimport { getFormattedLoad, getSuffix, getTotalAdded } from './helpers';\n\ninterface Props extends ModalProps<typeof Form> {\n    gateway: Gateway;\n    language: string | readonly string[];\n    countries: readonly string[];\n    deletedInCountries: Record<string, number>;\n    users: readonly GatewayUser[];\n    ownedCount: number;\n    usedCount: number;\n    showDeleted?: boolean;\n    showIPv4?: boolean;\n    showIPv6?: boolean;\n    showLoad?: boolean;\n    showCancelButton?: boolean;\n    singleServer?: boolean;\n    isDeleted: (logical: GatewayLogical) => boolean;\n    onSubmitDone: (deletedLogicalIds: readonly string[], addedQuantities: Record<string, number>) => Promise<void>;\n    onUpsell: () => void;\n}\n\nconst GatewayServersModal = ({\n    gateway,\n    language,\n    countries,\n    deletedInCountries,\n    users,\n    ownedCount,\n    usedCount,\n    showDeleted = false,\n    showIPv4 = true,\n    showIPv6 = true,\n    showLoad = true,\n    showCancelButton = false,\n    singleServer = false,\n    isDeleted,\n    onSubmitDone,\n    onUpsell,\n    ...rest\n}: Props) => {\n    const [addServersModal, showAddServersModal] = useModalTwoStatic(GatewayAddServersModal);\n    const [deleted, setDeleted] = useState<Record<string, boolean>>({});\n    const [added, setAdded] = useState<Record<string, number>>({});\n    const [loading, setLoading] = useState(false);\n    const remainingCount = ownedCount - usedCount;\n    const previousServers = gateway.Logicals.filter((l) => !l.Servers?.length || l.Visible);\n    const previousNumberOfServers = previousServers.length;\n    const deletedServers = previousServers.filter((l) => deleted[l.ID]);\n    const deletedServerCount = deletedServers.length;\n    const addedServerCount = Object.entries(added).reduce((total, [, quantity]) => total + quantity, 0);\n    const availableAddedCount = remainingCount + deletedServerCount - addedServerCount;\n    const newNumberOfServers = previousNumberOfServers + addedServerCount - deletedServerCount;\n    const showIP = showIPv4 || showIPv6;\n\n    const decreaseQuantities = (quantities: Record<string, number>) => {\n        const newAdded = { ...added };\n\n        Object.entries(quantities).forEach(([country, quantity]) => {\n            const newQuantity = (newAdded[country] || 0) - quantity;\n\n            if (newQuantity) {\n                newAdded[country] = newQuantity;\n\n                return;\n            }\n\n            delete newAdded[country];\n        });\n\n        setAdded(newAdded);\n    };\n\n    const addQuantities = (quantities: Record<string, number>) => {\n        const entries = Object.entries(quantities);\n\n        if (!entries.length) {\n            return;\n        }\n\n        const newAdded = { ...added };\n        let deletedIds = Object.keys(deleted).filter((id) => deleted[id]);\n\n        entries.forEach(([country, quantity]) => {\n            const serversFromTrash = gateway.Logicals.filter((l) => l.ExitCountry === country && l.ID && deleted[l.ID])\n                .map((l) => l.ID)\n                .slice(0, quantity);\n            const recoverableQuantity = serversFromTrash.length;\n\n            if (recoverableQuantity) {\n                deletedIds = deletedIds.filter((id) => serversFromTrash.indexOf(id) === -1);\n            }\n\n            const addedQuantity = quantity - recoverableQuantity;\n\n            if (addedQuantity > 0) {\n                newAdded[country] = (newAdded[country] || 0) + addedQuantity;\n            }\n        });\n\n        const newDeleted: Record<string, true> = {};\n\n        deletedIds.forEach((id) => {\n            newDeleted[id] = true;\n        });\n\n        setAdded(newAdded);\n        setDeleted(newDeleted);\n    };\n\n    const addServers = () =>\n        showAddServersModal({\n            countries,\n            deletedInCountries,\n            ownedCount,\n            usedCount: usedCount - deletedServerCount + addedServerCount,\n            users,\n            language,\n            singleServer,\n            showCancelButton,\n            onSubmitDone: addQuantities,\n            onUpsell,\n        });\n\n    const handleDelete = (logical: GatewayLogical) => async () => {\n        if (added[logical.ExitCountry] > 0) {\n            decreaseQuantities({ [logical.ExitCountry]: 1 });\n\n            return;\n        }\n\n        setDeleted({\n            ...deleted,\n            [logical.ID]: !deleted[logical.ID],\n        });\n    };\n\n    const handleSubmit = async () => {\n        const idsToDelete = Object.keys(deleted).filter((id) => deleted[id]);\n\n        if (getTotalAdded(added) < 1 && idsToDelete.length < 1) {\n            rest.onClose?.();\n\n            return;\n        }\n\n        try {\n            setLoading(true);\n            await onSubmitDone(idsToDelete, added);\n            rest.onClose?.();\n        } finally {\n            setLoading(false);\n        }\n    };\n\n    return (\n        <>\n            <ModalTwo size=\"xlarge\" {...rest} as={Form} onSubmit={handleSubmit}>\n                <ModalTwoHeader title={c('Title').t`Edit servers`} />\n                <ModalTwoContent>\n                    <Table className=\"my-2\">\n                        <thead>\n                            <tr>\n                                <TableCell key=\"country\" type=\"header\">{c('Header').t`Country`}</TableCell>\n                                <TableCell key=\"server\" type=\"header\" className=\"w-1/10\">\n                                    {c('Header').t`Server`}\n                                </TableCell>\n                                <TableCell key=\"status\" type=\"header\" className=\"w-1/6\">\n                                    {c('Header').t`Status`}\n                                </TableCell>\n                                {showIP && (\n                                    <TableCell key=\"ip\" type=\"header\" className=\"w-1/6\">\n                                        {c('Header').t`IP address`}\n                                    </TableCell>\n                                )}\n                                {showLoad && (\n                                    <TableCell key=\"load\" type=\"header\" className=\"w-1/6\">\n                                        {c('Header').t`Server load`}\n                                    </TableCell>\n                                )}\n                                <TableCell key=\"manage\" type=\"header\" className=\"w-1/10\">\n                                    &nbsp;\n                                </TableCell>\n                            </tr>\n                        </thead>\n                        <TableBody colSpan={4 + Number(showIP) + Number(showLoad)} loading={loading}>\n                            {gateway.Logicals.filter((l) => l.Servers?.length && l.Visible).map((logical) => (\n                                <TableRow\n                                    key={'logical-' + logical.ID}\n                                    className={deleted[logical.ID] ? 'opacity-50' : undefined}\n                                    cells={[\n                                        getCountryFlagAndName(language, logical.ExitCountry, undefined, {\n                                            className: 'mb-1',\n                                            key: `country-logical-${logical.ID}-${logical.ExitCountry}`,\n                                        }),\n                                        getSuffix(logical.Name),\n                                        <span className=\"py-1 px-2 rounded text-uppercase bg-success\">{\n                                            /** translator: status of the server: people can connect to it */\n                                            c('Server-Info').t`active`\n                                        }</span>,\n                                        ...(showIP\n                                            ? [\n                                                  <>\n                                                      {[\n                                                          showIPv4 && logical.Servers[0].ExitIPv4,\n                                                          showIPv6 && logical.Servers[0].ExitIPv6,\n                                                      ]\n                                                          .filter(Boolean)\n                                                          .map((ip) => (\n                                                              <div\n                                                                  key={'ip-' + ip}\n                                                                  className=\"text-ellipsis\"\n                                                                  title={ip || undefined}\n                                                              >\n                                                                  {ip}\n                                                              </div>\n                                                          ))}\n                                                  </>,\n                                              ]\n                                            : []),\n                                        ...(showLoad ? [getFormattedLoad(logical.Servers)] : []),\n                                        <Button icon size=\"small\" key=\"delete\" onClick={handleDelete(logical)}>\n                                            <Icon name=\"trash\" />\n                                        </Button>,\n                                    ]}\n                                />\n                            ))}\n                            {showDeleted &&\n                                gateway.Logicals.filter((l) => l.Servers?.length && !l.Visible).map((logical) => (\n                                    <TableRow\n                                        key={'logical-' + logical.ID}\n                                        className=\"opacity-50\"\n                                        cells={[\n                                            getCountryFlagAndName(language, logical.ExitCountry, undefined, {\n                                                className: 'mb-1',\n                                                key: 'country-logical-' + logical.ID + '-' + logical.ExitCountry,\n                                            }),\n                                            getSuffix(logical.Name),\n                                            <span className=\"py-1 px-2 rounded text-uppercase bg-weak color-weak\">{\n                                                /** translator: status of the server: people cannot connect to it */\n                                                c('Server-Info').t`inactive`\n                                            }</span>,\n                                            ...(showIP\n                                                ? [\n                                                      <>\n                                                          {[logical.Servers[0].ExitIPv4, logical.Servers[0].ExitIPv6]\n                                                              .filter(Boolean)\n                                                              .map((ip) => (\n                                                                  <div key={'ip-' + ip}>{ip}</div>\n                                                              ))}\n                                                      </>,\n                                                  ]\n                                                : []),\n                                            ...(showLoad ? [getFormattedLoad(logical.Servers)] : []),\n                                            '',\n                                        ]}\n                                    />\n                                ))}\n                            {gateway.Logicals.filter((l) => !l.Servers?.length).map((logical) => (\n                                <TableRow\n                                    key={'logical-' + logical.ID}\n                                    className={deleted[logical.ID] ? 'opacity-50' : undefined}\n                                    cells={[\n                                        getCountryFlagAndName(language, logical.ExitCountry, undefined, {\n                                            className: 'mb-1',\n                                            key: 'country-logical-' + logical.ID + '-' + logical.ExitCountry,\n                                        }),\n                                        getSuffix(logical.Name),\n                                        <span className=\"py-1 px-2 rounded text-uppercase bg-info\">{\n                                            /** translator: status of the server: people cannot yet use it */\n                                            c('Server-Info').t`pending`\n                                        }</span>,\n                                        ...(showIP ? ['-'] : []),\n                                        ...(showLoad ? ['-'] : []),\n                                        <Button icon size=\"small\" key=\"delete\" onClick={handleDelete(logical)}>\n                                            <Icon name=\"trash\" />\n                                        </Button>,\n                                    ]}\n                                />\n                            ))}\n                            {Object.keys(added).map((country) =>\n                                range(0, added[country]).map((index) => (\n                                    <TableRow\n                                        key={'future-logical-' + country + '-' + index}\n                                        cells={[\n                                            getCountryFlagAndName(language, country, undefined, {\n                                                className: 'mb-1',\n                                                key: 'country-future-logical-' + country + '-' + index,\n                                            }),\n                                            '',\n                                            new Cell(\n                                                (\n                                                    <span className=\"py-1 px-2 rounded text-uppercase bg-weak\">{\n                                                        /** translator: status of the server: will be created when user click \"Save\" */\n                                                        c('Server-Info').t`to be created`\n                                                    }</span>\n                                                ),\n                                                1 + Number(showIP) + Number(showLoad)\n                                            ),\n                                            <Button\n                                                icon\n                                                size=\"small\"\n                                                key=\"delete\"\n                                                onClick={() => {\n                                                    decreaseQuantities({ [country]: 1 });\n                                                }}\n                                            >\n                                                <Icon name=\"trash\" />\n                                            </Button>,\n                                        ]}\n                                    />\n                                ))\n                            )}\n                        </TableBody>\n                    </Table>\n                    {availableAddedCount >= 1 ? (\n                        <Button shape=\"ghost\" className=\"color-primary\" onClick={addServers}>\n                            <Icon name=\"plus-circle-filled\" className=\"mr-2\" />\n                            {c('Info').ngettext(\n                                msgid`Add server (${availableAddedCount} available)`,\n                                `Add server (${availableAddedCount} available)`,\n                                availableAddedCount\n                            )}\n                        </Button>\n                    ) : (\n                        ownedCount < MAX_IPS_ADDON && (\n                            <Button\n                                shape=\"ghost\"\n                                className=\"color-primary\"\n                                onClick={() => {\n                                    onUpsell();\n                                    rest.onClose?.();\n                                }}\n                            >\n                                <Icon name=\"plus-circle-filled\" className=\"mr-2\" />\n                                {c('Action').t`Get more servers`}\n                            </Button>\n                        )\n                    )}\n                </ModalTwoContent>\n                <ModalTwoFooter>\n                    {showCancelButton ? (\n                        <Button color=\"weak\" onClick={rest.onClose}>\n                            {c('Action').t`Cancel`}\n                        </Button>\n                    ) : (\n                        <div />\n                    )}\n                    <Button color={newNumberOfServers ? 'norm' : 'danger'} type=\"submit\" loading={loading}>\n                        {newNumberOfServers ? c('Action').t`Save` : c('Action').t`Delete Gateway`}\n                    </Button>\n                </ModalTwoFooter>\n            </ModalTwo>\n            {addServersModal}\n        </>\n    );\n};\n\nexport default GatewayServersModal;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Form,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n} from '@proton/components/components';\n\nimport { GatewayDto } from './GatewayDto';\nimport { GatewayModel } from './GatewayModel';\nimport { GatewayUser } from './GatewayUser';\nimport { GatewayUserSelection } from './GatewayUserSelection';\n\ntype PartialGateway = Pick<GatewayDto, 'features' | 'userIds'>;\n\ninterface Props extends ModalProps<typeof Form> {\n    model: PartialGateway;\n    users: readonly GatewayUser[];\n    showCancelButton?: boolean;\n    onSubmitDone: (gateway: Pick<GatewayModel, 'Features' | 'UserIds'>) => Promise<void>;\n}\n\nconst GatewayUsersModal = ({ model: initialModel, users, showCancelButton = false, onSubmitDone, ...rest }: Props) => {\n    const [model, setModel] = useState<PartialGateway>({ ...initialModel });\n    const [loading, setLoading] = useState(false);\n\n    const changeModel = (diff: Partial<PartialGateway>) => setModel((model) => ({ ...model, ...diff }));\n\n    const handleSubmit = async () => {\n        const dtoBody = {\n            Features: model.features,\n            UserIds: model.userIds,\n        };\n\n        try {\n            setLoading(true);\n            await onSubmitDone(dtoBody);\n            rest.onClose?.();\n        } finally {\n            setLoading(false);\n        }\n    };\n\n    return (\n        <ModalTwo size=\"xlarge\" {...rest} as={Form} onSubmit={handleSubmit}>\n            <ModalTwoHeader title={c('Title').t`Edit users`} />\n            <ModalTwoContent>\n                <GatewayUserSelection loading={loading} users={users} model={model} changeModel={changeModel} />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                {showCancelButton ? (\n                    <Button color=\"weak\" onClick={rest.onClose}>\n                        {c('Action').t`Cancel`}\n                    </Button>\n                ) : (\n                    <div />\n                )}\n                <Button color=\"norm\" type=\"submit\" loading={loading}>\n                    {c('Action').t`Save`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default GatewayUsersModal;\n","import { GatewayIpModel } from '@proton/components/containers/vpn/gateways/GatewayIpModel';\n\nimport { GatewayModel } from './GatewayModel';\n\nexport const queryVPNGateways = () => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'get',\n});\n\nexport const createVPNGateway = (data: GatewayModel) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'post',\n    data,\n});\n\nexport const addIpInVPNGateway = (data: GatewayIpModel) => ({\n    url: 'vpn/v1/business/gateways/ip',\n    method: 'post',\n    data,\n});\n\nexport const deleteVPNGateway = (ids: readonly string[]) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'delete',\n    data: {\n        LogicalIds: ids,\n    },\n});\n\nexport const renameVPNGateway = (currentName: string, newName: string) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'put',\n    data: {\n        CurrentName: currentName,\n        NewName: newName,\n    },\n});\n\nexport const updateVPNGatewayUsers = (currentName: string, features: number, userIds?: readonly string[] | null) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'put',\n    data: {\n        CurrentName: currentName,\n        NewName: currentName,\n        Features: features,\n        UserIds: userIds ?? null,\n    },\n});\n","import { c, msgid } from 'ttag';\n\nimport { useApiResult } from '@proton/components/hooks';\n\nimport { Gateway } from './Gateway';\nimport { GatewayUser } from './GatewayUser';\nimport { queryVPNGateways } from './api';\n\ninterface TableConfig {\n    Name: boolean;\n    Status: boolean;\n    Country: boolean;\n    IPv4: boolean;\n    IPv6: boolean;\n    Load: boolean;\n    Deleted?: boolean;\n}\n\ninterface GatewayConfig {\n    Table: TableConfig;\n    ServerTable: TableConfig;\n    Provisioning: {\n        TranslatedDuration: string;\n    };\n}\n\nexport const useGateways = () => {\n    const {\n        loading,\n        result,\n        request: refresh,\n    } = useApiResult<\n        {\n            Config: GatewayConfig;\n            Countries: readonly string[];\n            Gateways: readonly Gateway[];\n            Users: readonly GatewayUser[];\n        },\n        typeof queryVPNGateways\n    >(queryVPNGateways, []);\n\n    const nbDay = 7;\n\n    return {\n        loading: !result || loading,\n        config: result?.Config || {\n            Table: {\n                Name: false,\n                Status: true,\n                Country: true,\n                IPv4: true,\n                IPv6: false,\n                Load: false,\n            },\n            ServerTable: {\n                Name: false,\n                Status: true,\n                Country: true,\n                IPv4: true,\n                IPv6: false,\n                Load: true,\n            },\n            Provisioning: {\n                TranslatedDuration: c('Label').ngettext(msgid`${nbDay} day`, `${nbDay} days`, nbDay),\n            },\n        },\n        countries: result?.Countries,\n        gateways: result?.Gateways,\n        users: result?.Users || [],\n        refresh,\n    };\n};\n\nexport default useGateways;\n","import React, { useMemo, useState } from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { Button, Href } from '@proton/atoms';\nimport { PLANS, SERVER_FEATURES, SORT_DIRECTION } from '@proton/shared/lib/constants';\nimport { getNonEmptyErrorMessage } from '@proton/shared/lib/helpers/error';\nimport { getVPNDedicatedIPs } from '@proton/shared/lib/helpers/subscription';\nimport { Organization } from '@proton/shared/lib/interfaces';\nimport gatewaySvg from '@proton/styles/assets/img/illustrations/gateway.svg';\nimport gatewaysEmptyStateAdminsSvg from '@proton/styles/assets/img/illustrations/gateways-empty-state-admins.svg';\nimport gatewaysEmptyStateUsersSvg from '@proton/styles/assets/img/illustrations/gateways-empty-state-users.svg';\n\nimport { Loader, Table, TableBody, TableCell, useModalTwoStatic } from '../../../components';\nimport SettingsSectionWide from '../../../containers/account/SettingsSectionWide';\nimport { EmptyViewContainer } from '../../../containers/app';\nimport PromotionBanner from '../../../containers/banner/PromotionBanner';\nimport { SUBSCRIPTION_STEPS, useSubscriptionModal } from '../../../containers/payments';\nimport { useApi, useNotifications, useSortedList, useSubscription, useUser, useUserSettings } from '../../../hooks';\nimport { Gateway } from './Gateway';\nimport { GatewayLogical } from './GatewayLogical';\nimport GatewayModal from './GatewayModal';\nimport { GatewayModel } from './GatewayModel';\nimport GatewayRenameModal from './GatewayRenameModal';\nimport GatewayRow from './GatewayRow';\nimport GatewayServersModal from './GatewayServersModal';\nimport GatewayUsersModal from './GatewayUsersModal';\nimport { addIpInVPNGateway, createVPNGateway, deleteVPNGateway, renameVPNGateway, updateVPNGatewayUsers } from './api';\nimport { useGateways } from './useGateways';\n\ninterface Props {\n    organization?: Organization;\n    showCancelButton?: boolean;\n}\n\nconst getFeaturesAndUserIds = (data: Partial<GatewayModel>): [number, readonly string[] | null] => {\n    const features = data.Features || 0;\n\n    return [features, features & SERVER_FEATURES.DOUBLE_RESTRICTION ? data.UserIds || [] : null];\n};\n\nconst GatewaysSection = ({ organization, showCancelButton = true }: Props) => {\n    const api = useApi();\n    const [createModal, showCreateModal] = useModalTwoStatic(GatewayModal);\n    const [renameModal, showRenameModal] = useModalTwoStatic(GatewayRenameModal);\n    const [usersModal, showUsersModal] = useModalTwoStatic(GatewayUsersModal);\n    const [serversModal, showServersModal] = useModalTwoStatic(GatewayServersModal);\n    const [user] = useUser();\n    const { createNotification } = useNotifications();\n    const [userSettings] = useUserSettings();\n    const [subscription] = useSubscription();\n    const [deletedLogicals, setDeletedLogicals] = useState<Record<string, boolean>>({});\n    const [deletingLogicals, setDeletingLogicals] = useState<readonly string[]>([]);\n    const [createdGateways, setCreatedGateways] = useState<Gateway[]>([]);\n    const [updatedLogicals, setUpdatedLogicals] = useState<Record<string, GatewayLogical>>({});\n    const {\n        config: {\n            Table: { IPv4, IPv6, Load, Deleted },\n            ServerTable: serverTableConfig,\n            Provisioning: { TranslatedDuration: provisioningDuration },\n        },\n        users,\n        countries,\n        gateways,\n        refresh,\n    } = useGateways();\n    const refreshList = async () => {\n        setCreatedGateways([]);\n        setUpdatedLogicals({});\n        await refresh();\n    };\n    const allGateways = useMemo<readonly Gateway[]>(() => {\n        const ids: Record<string, true> = {};\n\n        return [...createdGateways, ...(gateways || [])]\n            .map((gateway) => ({\n                ...gateway,\n                Logicals: gateway.Logicals.filter((l) => !deletedLogicals[l.ID]).map((l) => updatedLogicals[l.ID] || l),\n            }))\n            .filter((gateway) => {\n                if (ids[gateway.Name]) {\n                    return false;\n                }\n\n                if (gateway.Logicals.length) {\n                    ids[gateway.Name] = true;\n\n                    return true;\n                }\n\n                return false;\n            });\n    }, [createdGateways, gateways, updatedLogicals, deletedLogicals]);\n    const { sortedList } = useSortedList(allGateways as Gateway[], { key: 'Name', direction: SORT_DIRECTION.ASC });\n    const [openSubscriptionModal] = useSubscriptionModal();\n\n    if (!organization || !user || !subscription || !gateways || !countries) {\n        return <Loader />;\n    }\n\n    const createGateway = async (apiRequest: any): Promise<Gateway> => {\n        const createdGateway = (await api<{ Gateway: Gateway }>(apiRequest))?.Gateway;\n\n        const newDeletedLogicals = { ...deletedLogicals };\n        const newUpdatedLogicals = { ...updatedLogicals };\n        let touched = false;\n\n        createdGateway.Logicals?.forEach((logical) => {\n            if ((newUpdatedLogicals[logical.ID] || newDeletedLogicals[logical.ID]) && logical.Visible) {\n                touched = true;\n\n                newUpdatedLogicals[logical.ID] = logical;\n                delete newDeletedLogicals[logical.ID];\n            }\n        });\n\n        if (touched) {\n            setDeletedLogicals(newDeletedLogicals);\n            setUpdatedLogicals(newUpdatedLogicals);\n        }\n\n        return createdGateway;\n    };\n\n    const getCustomizeSubscriptionOpener = (source: 'dashboard' | 'upsells') => () =>\n        openSubscriptionModal({\n            metrics: {\n                source,\n            },\n            step: SUBSCRIPTION_STEPS.CHECKOUT_WITH_CUSTOMIZATION,\n            plan: PLANS.VPN_BUSINESS,\n        });\n\n    const isAdmin = user.isAdmin && !user.isSubUser;\n\n    if (organization.PlanName !== PLANS.VPN_BUSINESS) {\n        const boldDedicatedServers = (\n            <b key=\"bold-dedicated-servers\">{\n                // translator: Full sentence \"With a Business or Enterprise plan, you can purchase dedicated servers for your organization, and set up Gateways to control which users can access them\"\n                c('Info').t`dedicated servers`\n            }</b>\n        );\n        const boldGateways = (\n            <b key=\"bold-gateways\">{\n                // translator: Full sentence \"With a Business or Enterprise plan, you can purchase dedicated servers for your organization, and set up Gateways to control which users can access them\"\n                c('Info').t`Gateways`\n            }</b>\n        );\n\n        return (\n            <SettingsSectionWide>\n                <PromotionBanner\n                    rounded\n                    mode=\"banner\"\n                    contentCentered={false}\n                    icon={<img src={gatewaySvg} alt=\"\" width={40} height={40} />}\n                    description={\n                        <div>\n                            <b>{c('Info').t`Enhance your network security`}</b>\n                            <div>\n                                {\n                                    // translator: Full sentence \"With a Business or Enterprise plan, you can purchase dedicated servers for your organization, and set up Gateways to control which users can access them\"\n                                    c('Info')\n                                        .jt`With a Business or Enterprise plan, you can purchase ${boldDedicatedServers} for your organization, and set up ${boldGateways} to control which users can access them.`\n                                }{' '}\n                                <Href\n                                    href=\"https://protonvpn.com/support/manage-vpn-servers-organization\"\n                                    title={c('Info').t`Lean more about gateways`}\n                                >{c('Link').t`Learn more`}</Href>\n                            </div>\n                        </div>\n                    }\n                    cta={\n                        isAdmin && (\n                            <Button\n                                color=\"norm\"\n                                fullWidth\n                                onClick={getCustomizeSubscriptionOpener('upsells')}\n                                title={c('Title').t`Setup dedicated servers by upgrading to Business`}\n                            >\n                                {c('Action').t`Upgrade to Business`}\n                            </Button>\n                        )\n                    }\n                />\n            </SettingsSectionWide>\n        );\n    }\n\n    const isDeleted = (logical: GatewayLogical): boolean => !logical.Visible && logical.Servers?.length > 0;\n\n    const ipAddresses = getVPNDedicatedIPs(subscription);\n    const deletedInCountries: Record<string, number> = {};\n    const ipCount = allGateways.reduce((total, gateway) => {\n        return (\n            total +\n            gateway.Logicals.reduce((sum, logical) => {\n                if (isDeleted(logical)) {\n                    deletedInCountries[gateway.ExitCountry] = (deletedInCountries[gateway.ExitCountry] || 0) + 1;\n\n                    return sum;\n                }\n\n                return sum + Math.max(1, logical.Servers?.length || 0);\n            }, 0)\n        );\n    }, 0);\n    const canAdd = ipAddresses > ipCount;\n    const language = userSettings.Locale || navigator.languages;\n\n    const createServersSequentially = async (\n        data: GatewayModel,\n        initialGateway?: Gateway,\n        key = 'gateway-creation',\n        getNotificationMessage?: (serverNumber: number, total: number) => string\n    ): Promise<Gateway | undefined> => {\n        const quantities = data.Quantities;\n\n        if (!quantities) {\n            return;\n        }\n\n        const countries = Object.keys(quantities);\n        const total = countries.reduce((total, country) => total + (quantities[country] || 0), 0);\n        let gatewayHost: Gateway | undefined = initialGateway;\n        let serverNumber = 0;\n\n        for (let i = 0; i < countries.length; i++) {\n            const country = countries[i];\n\n            for (let j = 0; j < quantities[country]; j++) {\n                ++serverNumber;\n\n                createNotification({\n                    key,\n                    text: getNotificationMessage\n                        ? getNotificationMessage(serverNumber, total)\n                        : /*\n                        translator: \"Creating gateway servers\" refers to the whole operation, so pluralization uses ${total}, not ${serverNumber}, \"Creating gateway servers: 1 / 3\" is plural in English because we are creating a gateway of 3 servers\n                        translator: This message appears when starting to creating a gateway that will contain ${total} server in the end (total is always an integer and at least 2, so for any language with \"One\" form < 2, don't care much about singular)\n                        */ c('Info').ngettext(\n                              msgid`Creating gateway server: ${serverNumber} / ${total}`,\n                              `Creating gateway servers: ${serverNumber} / ${total}`,\n                              total\n                          ),\n                    type: 'info',\n                });\n\n                if (!gatewayHost) {\n                    const [features, usersIds] = getFeaturesAndUserIds(data);\n\n                    gatewayHost = await createGateway(\n                        createVPNGateway({\n                            Name: data.Name,\n                            Country: country,\n                            Features: features,\n                            UserIds: usersIds,\n                        })\n                    );\n\n                    continue;\n                }\n\n                try {\n                    gatewayHost = await createGateway(\n                        addIpInVPNGateway({\n                            Name: gatewayHost.Name,\n                            Country: country,\n                        })\n                    );\n                } catch (error) {\n                    createNotification({\n                        key,\n                        text: getNonEmptyErrorMessage(error),\n                        type: 'warning',\n                    });\n\n                    return gatewayHost;\n                }\n            }\n        }\n\n        return gatewayHost;\n    };\n\n    const buildGateway = async (data: GatewayModel): Promise<Gateway | undefined> => {\n        if (data.Quantities) {\n            return createServersSequentially(data);\n        }\n\n        const [features, usersIds] = getFeaturesAndUserIds(data);\n\n        return createGateway(\n            createVPNGateway({\n                Name: data.Name,\n                Country: data.Country,\n                Features: features,\n                UserIds: usersIds,\n            })\n        );\n    };\n\n    const addGateway = () =>\n        showCreateModal({\n            showCancelButton,\n            countries,\n            deletedInCountries,\n            ownedCount: ipAddresses,\n            usedCount: ipCount,\n            users,\n            language,\n            onSubmitDone: async (data: GatewayModel) => {\n                const gateway = await buildGateway(data);\n\n                if (!gateway) {\n                    createNotification({\n                        text: c('Error').t`Impossible to create the gateway`,\n                        type: 'error',\n                    });\n\n                    return;\n                }\n\n                setCreatedGateways([...createdGateways, gateway]);\n            },\n            onUpsell: getCustomizeSubscriptionOpener('dashboard'),\n        });\n\n    const editGatewayServers = (gateway: Gateway) => () =>\n        showServersModal({\n            language,\n            showCancelButton,\n            gateway,\n            countries,\n            deletedInCountries,\n            users,\n            ownedCount: ipAddresses,\n            usedCount: ipCount,\n            showDeleted: serverTableConfig.Deleted,\n            showIPv4: serverTableConfig.IPv4,\n            showIPv6: serverTableConfig.IPv6,\n            showLoad: serverTableConfig.Load,\n            isDeleted,\n            onSubmitDone: async (deletedLogicalIds: readonly string[], addedQuantities: Record<string, number>) => {\n                const deletedServerCount = deletedLogicalIds.length;\n                const addedServerCount = Object.entries(addedQuantities).reduce(\n                    (total, [, quantity]) => total + quantity,\n                    0\n                );\n\n                if (deletedServerCount && addedServerCount) {\n                    createNotification({\n                        key: 'gateway-servers-editions',\n                        text: c('Info').ngettext(\n                            msgid`Deleting ${deletedServerCount} gateway server`,\n                            `Deleting ${deletedServerCount} gateway servers`,\n                            deletedServerCount\n                        ),\n                        type: 'info',\n                    });\n                }\n\n                if (deletedServerCount) {\n                    await api(deleteVPNGateway(deletedLogicalIds));\n                }\n\n                if (deletedServerCount && addedServerCount) {\n                    createNotification({\n                        key: 'gateway-servers-editions',\n                        text: c('Info').ngettext(\n                            msgid`Adding ${addedServerCount} gateway server`,\n                            `Adding ${addedServerCount} gateway servers`,\n                            addedServerCount\n                        ),\n                        type: 'info',\n                    });\n                }\n\n                if (addedServerCount) {\n                    await createServersSequentially(\n                        {\n                            Name: gateway.Name,\n                            Features: gateway.Logicals[0]?.Features,\n                            UserIds: gateway.Logicals[0]?.Users,\n                            Quantities: addedQuantities,\n                        },\n                        gateway,\n                        'gateway-servers-editions',\n                        (serverNumber: number, total: number) =>\n                            /*\n                            translator: \"Creating gateway servers\" refers to the whole operation, so pluralization uses ${total}, not ${serverNumber}, \"Creating gateway servers: 1 / 3\" is plural in English because we are creating a gateway of 3 servers\n                            translator: This message appears when starting to creating a gateway that will contain ${total} server in the end (total is always an integer and at least 2, so for any language with \"One\" form < 2, don't care much about singular)\n                            */ c('Info').ngettext(\n                                msgid`Adding gateway server: ${serverNumber} / ${total}`,\n                                `Adding gateway servers: ${serverNumber} / ${total}`,\n                                total\n                            )\n                    );\n                }\n\n                await refreshList();\n            },\n            onUpsell: getCustomizeSubscriptionOpener('dashboard'),\n        });\n\n    const editGatewayUsers = (gateway: Gateway, logical: GatewayLogical) => () =>\n        showUsersModal({\n            showCancelButton,\n            model: {\n                features: logical.Features,\n                userIds: logical.Users,\n            },\n            users,\n            onSubmitDone: async (data: GatewayModel) => {\n                const [features, usersIds] = getFeaturesAndUserIds(data);\n\n                const update = await api<{ Gateway: Gateway }>(updateVPNGatewayUsers(gateway.Name, features, usersIds));\n\n                if (!update?.Gateway) {\n                    createNotification({\n                        text: c('Error').t`Impossible to edit the gateway`,\n                        type: 'error',\n                    });\n\n                    return;\n                }\n\n                await refreshList();\n            },\n        });\n\n    const renameGateway = (id: string, currentName: string) => () => {\n        if (deletingLogicals.indexOf(id) !== -1) {\n            return;\n        }\n\n        showRenameModal({\n            showCancelButton,\n            currentName,\n            onSubmitDone: async ({ Name: newName }: { Name: string }) => {\n                const gateway = await api<{ Gateway: Gateway }>(renameVPNGateway(currentName, newName));\n\n                if (!gateway?.Gateway) {\n                    createNotification({\n                        text: c('Error').t`Impossible to rename the gateway`,\n                        type: 'error',\n                    });\n\n                    return;\n                }\n\n                await refreshList();\n            },\n        });\n    };\n\n    const deleteGateway = (gateway: Gateway) => async () => {\n        const ids = gateway.Logicals.map(({ ID }) => ID);\n\n        if (deletingLogicals.some((id) => ids.indexOf(id) !== -1)) {\n            return;\n        }\n\n        setDeletingLogicals([...deletingLogicals, ...ids]);\n\n        try {\n            const { Logicals: logicals } = await api<{ Logicals: GatewayLogical[] }>(deleteVPNGateway(ids));\n            const update = { ...updatedLogicals };\n            const kept: Record<string, boolean> = {};\n\n            logicals.forEach((logical) => {\n                kept[logical.ID] = true;\n                update[logical.ID] = logical;\n            });\n\n            setUpdatedLogicals(update);\n\n            if (ids.length !== Object.keys(kept).length) {\n                const removed: Record<string, boolean> = { ...deletedLogicals };\n\n                ids.forEach((id) => {\n                    if (!kept[id]) {\n                        removed[id] = true;\n                    }\n                });\n\n                setDeletedLogicals(removed);\n            }\n        } finally {\n            setDeletingLogicals(deletingLogicals.filter((deletingId) => ids.indexOf(deletingId) === -1));\n        }\n    };\n\n    return (\n        <>\n            {isAdmin && (\n                <>\n                    {createModal}\n                    {renameModal}\n                    {serversModal}\n                    {usersModal}\n                    <div className=\"mb-4 flex items-center gap-2\">\n                        <span className=\"color-weak\">\n                            {c('Info').ngettext(\n                                msgid`You are currently using ${ipCount} of your ${ipAddresses} available dedicated server.`,\n                                `You are currently using ${ipCount} of your ${ipAddresses} available dedicated servers.`,\n                                ipAddresses\n                            )}\n                        </span>\n                        <Button\n                            size=\"small\"\n                            color=\"norm\"\n                            shape={canAdd ? 'outline' : 'solid'}\n                            onClick={getCustomizeSubscriptionOpener('dashboard')}\n                            title={c('Title').t`Customize the number of IP addresses in your plan`}\n                        >\n                            {c('Action').t`Get more servers`}\n                        </Button>\n                    </div>\n                </>\n            )}\n\n            {sortedList.length ? (\n                <>\n                    {isAdmin && (\n                        <div className=\"mb-4\">\n                            <Button\n                                color=\"norm\"\n                                disabled={!canAdd}\n                                onClick={addGateway}\n                                title={c('Title').t`Create a new Gateway`}\n                            >\n                                {c('Action').t`Create Gateway`}\n                            </Button>\n                        </div>\n                    )}\n\n                    <Table className=\"my-2\">\n                        <thead>\n                            <tr>\n                                <TableCell key=\"name\" type=\"header\">{c('Header').t`Name`}</TableCell>\n                                <TableCell key=\"status\" type=\"header\" className=\"w-1/10\">\n                                    {c('Header').t`Status`}\n                                </TableCell>\n                                <TableCell key=\"servers\" type=\"header\">{c('Header').t`Servers`}</TableCell>\n                                {isAdmin && (\n                                    <>\n                                        <TableCell key=\"members\" type=\"header\">{c('Header').t`Members`}</TableCell>\n                                        <TableCell\n                                            key=\"manage\"\n                                            type=\"header\"\n                                            className=\"w-custom\"\n                                            style={{ '--w-custom': '12rem' }}\n                                        >\n                                            &nbsp;\n                                        </TableCell>\n                                    </>\n                                )}\n                            </tr>\n                        </thead>\n                        <TableBody colSpan={3 + (isAdmin ? 2 : 0)}>\n                            {sortedList.map((gateway) => (\n                                <GatewayRow\n                                    key={'gateway-' + gateway.Name}\n                                    isAdmin={isAdmin}\n                                    showDeleted={Deleted}\n                                    showIPv4={IPv4}\n                                    showIPv6={IPv6}\n                                    showLoad={Load}\n                                    gateway={gateway}\n                                    isDeleted={isDeleted}\n                                    users={users ?? []}\n                                    language={language}\n                                    provisioningDuration={provisioningDuration}\n                                    renameGateway={renameGateway}\n                                    editGatewayServers={editGatewayServers}\n                                    editGatewayUsers={editGatewayUsers}\n                                    deleteGateway={deleteGateway}\n                                    deletingLogicals={deletingLogicals}\n                                    deletedLogicals={deletedLogicals}\n                                />\n                            ))}\n                        </TableBody>\n                    </Table>\n                </>\n            ) : (\n                <EmptyViewContainer\n                    key=\"no-gateways-container\"\n                    imageProps={{\n                        src: isAdmin ? gatewaysEmptyStateAdminsSvg : gatewaysEmptyStateUsersSvg,\n                        title: c('Info').t`No gateways`,\n                        key: 'no-gateways-image',\n                    }}\n                >\n                    <h3 className=\"text-bold\">\n                        {isAdmin ? c('Info').t`Create your first Gateway` : c('Info').t`No Gateways yet`}\n                    </h3>\n                    <p className=\"color-weak\">\n                        {isAdmin\n                            ? c('Info')\n                                  .t`Organize your dedicated servers into Gateways and decide which members can access them.`\n                            : c('Info').t`Ask your organisation admin to setup Gateways.`}\n                    </p>\n\n                    {isAdmin && (\n                        <div>\n                            <Button\n                                color=\"norm\"\n                                disabled={!canAdd}\n                                onClick={addGateway}\n                                title={c('Title').t`Create a new gateway`}\n                            >\n                                {c('Action').t`Create Gateway`}\n                            </Button>\n                        </div>\n                    )}\n                </EmptyViewContainer>\n            )}\n        </>\n    );\n};\n\nexport default GatewaysSection;\n","import {\n    PrivateMainArea,\n    SettingsPageTitle,\n    SettingsParagraph,\n    SettingsSection,\n    SettingsSectionTitle,\n} from '@proton/components';\n\nconst PrivateMainAreaLoading = () => {\n    return (\n        <PrivateMainArea>\n            <div className=\"container-section-sticky\">\n                <SettingsPageTitle className=\"my-14 settings-loading-page-title\" />\n                <section className=\"container-section-sticky-section\">\n                    <SettingsSectionTitle className=\"settings-loading-section-title\" />\n                    <SettingsSection>\n                        <SettingsParagraph className=\"mb-4\">\n                            <span className=\"block settings-loading-paragraph-line\" />\n                            <span className=\"block settings-loading-paragraph-line\" />\n                            <span className=\"block settings-loading-paragraph-line\" />\n                        </SettingsParagraph>\n                    </SettingsSection>\n                </section>\n            </div>\n        </PrivateMainArea>\n    );\n};\nexport default PrivateMainAreaLoading;\n","import { c } from 'ttag';\n\nimport { useGetScheduleCall } from '@proton/account/scheduleCall/hooks';\nimport { Button } from '@proton/atoms/Button';\nimport { Href } from '@proton/atoms/Href';\nimport useLoading from '@proton/hooks/useLoading';\nimport { openCalendlyLink } from '@proton/shared/lib/helpers/support';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport illustration from '@proton/styles/assets/img/illustrations/account-support-phone.svg';\n\nimport { useUser } from '../../hooks';\nimport { SettingsSection } from '../account';\n\ninterface Props {\n    onOpenChat?: () => void;\n}\n\nconst OrganizationScheduleCallSection = ({ onOpenChat }: Props) => {\n    const [user] = useUser();\n    const [generatingCalendlyLink, withGeneratingCalendlyLink] = useLoading();\n    const getScheduleCall = useGetScheduleCall();\n\n    const handleScheduleCallClick = async () => {\n        const { CalendlyLink } = await getScheduleCall();\n\n        openCalendlyLink(CalendlyLink, user);\n    };\n\n    const boldPhoneCall = (\n        <b key=\"bold-phone-call\">{\n            // translator: Full sentence is 'Request a phone call or Zoom meeting with one of our support specialists, ...'\n            c('Info').t`Request a phone call`\n        }</b>\n    );\n\n    const boldZoomMeeting = (\n        <b key=\"bold-zoom-meeting\">{\n            // translator: Full sentence is 'Request a phone call or Zoom meeting with one of our support specialists, ...'\n            c('Info').t`Zoom meeting`\n        }</b>\n    );\n\n    const boldLiveChat = (\n        <b key=\"bold-live-chat\">{\n            // translator: Request a phone call or Zoom meeting with one of our support specialists, or open a Live chat for chat support.'\n            c('Info').t`Live chat`\n        }</b>\n    );\n\n    return (\n        <SettingsSection className=\"border rounded-lg p-4 lg:p-6 flex flex-column lg:flex-row items-center lg:items-start flex-nowrap text-center lg:text-left gap-4\">\n            <img src={illustration} alt=\"\" className=\"w-custom shrink-0\" style={{ '--w-custom': '3rem' }} />\n            <div>\n                <h2 className=\"text-lg text-bold mb-4\">{c('Headline').t`Contact us`}</h2>\n                <p className=\"mb-5\">\n                    {onOpenChat\n                        ? // translator: Full sentence is 'If you’re having trouble, we’re here to help. Request a phone call or Zoom meeting with one of our support specialists, or open a Live chat for chat support.'\n                          c('Info')\n                              .jt`If you’re having trouble, we’re here to help. ${boldPhoneCall} or ${boldZoomMeeting} with one of our support specialists, or open a ${boldLiveChat} for chat support.`\n                        : // translator: Full sentence is 'If you’re having trouble, we’re here to help. Request a phone call or Zoom meeting with one of our support specialists.'\n                          c('Info')\n                              .jt`If you’re having trouble, we’re here to help. ${boldPhoneCall} or ${boldZoomMeeting} with one of our support specialists.`}{' '}\n                    <Href className=\"inline-block\" href={getKnowledgeBaseUrl('/request-b2b-phone-support')}>\n                        {c('Link').t`Learn more`}\n                    </Href>\n                </p>\n                <div className=\"flex gap-4 justify-center lg:justify-start\">\n                    <Button\n                        onClick={() => withGeneratingCalendlyLink(handleScheduleCallClick)}\n                        color=\"norm\"\n                        shape=\"outline\"\n                        loading={generatingCalendlyLink}\n                    >\n                        {c('Action').t`Request a call`}\n                    </Button>\n                    {onOpenChat && (\n                        <Button color=\"norm\" shape=\"outline\" onClick={onOpenChat}>\n                            {c('Action').t`Start live chat`}\n                        </Button>\n                    )}\n                </div>\n            </div>\n        </SettingsSection>\n    );\n};\n\nexport default OrganizationScheduleCallSection;\n","import { c, msgid } from 'ttag';\n\nimport { Card } from '@proton/atoms';\nimport { useMembers } from '@proton/components';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport { Loader } from '../../components';\n\ninterface Props {\n    organization?: Organization;\n}\n\nconst OrganizationTwoFAHeader = ({ organization }: Props) => {\n    const [members] = useMembers();\n\n    if (!organization || !members) {\n        return <Loader />;\n    }\n\n    const twoFAMembers = members.filter((member) => member['2faStatus'] !== 0) || [];\n\n    // translator: the variables here are numbers, e.g. \"2/4 of your organization members use two-factor authentication.\"\n    const cardContent = c('Loading info').ngettext(\n        msgid`${twoFAMembers.length}/${members.length} of your organization member use two-factor authentication.`,\n        `${twoFAMembers.length}/${members.length} of your organization members use two-factor authentication.`,\n        members.length\n    );\n\n    return (\n        <Card rounded background bordered={false} className=\"max-w-custom\" style={{ '--max-w-custom': '43em' }}>\n            {cardContent}\n        </Card>\n    );\n};\n\nexport default OrganizationTwoFAHeader;\n","import { c } from 'ttag';\n\nimport { Avatar, Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { sendEmailReminderTwoFA } from '@proton/shared/lib/api/organization';\nimport { MEMBER_ROLE } from '@proton/shared/lib/constants';\nimport { getInitials } from '@proton/shared/lib/helpers/string';\nimport { Address, Member, PartialMemberAddress } from '@proton/shared/lib/interfaces';\nimport noop from '@proton/utils/noop';\n\nimport {\n    Badge,\n    Form,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    useFormErrors,\n} from '../../components';\nimport { useApi, useEventManager, useNotifications } from '../../hooks';\n\ninterface Props extends ModalProps {\n    members: Member[];\n    memberAddressesMap: { [key: string]: (Address | PartialMemberAddress)[] | undefined };\n}\n\nconst SendEmailReminderTwoFAModal = ({ onClose, members, memberAddressesMap, ...rest }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const { onFormSubmit } = useFormErrors();\n    const [loading, withLoading] = useLoading();\n\n    const handleSubmit = async () => {\n        await api(sendEmailReminderTwoFA());\n        await call();\n        createNotification({ text: c('Notification').t`Reminder has been sent` });\n        onClose?.();\n    };\n\n    const handleClose = loading ? noop : onClose;\n\n    return (\n        <Modal\n            as={Form}\n            onSubmit={() => {\n                if (!onFormSubmit()) {\n                    return;\n                }\n                void withLoading(handleSubmit());\n            }}\n            onClose={handleClose}\n            {...rest}\n        >\n            <ModalHeader title={c('Title').t`Send email reminders?`} />\n            <ModalContent>\n                <p>{c('Info')\n                    .t`The following members will receive an email prompting them to enable two-factor authentication as soon as possible.`}</p>\n                <ul className=\"unstyled\">\n                    {members\n                        .filter(function (member) {\n                            const memberAddresses = memberAddressesMap?.[member.ID] || [];\n                            return memberAddresses.length > 0;\n                        })\n                        .map((member) => {\n                            const memberAddresses = memberAddressesMap?.[member.ID] || [];\n                            return (\n                                <li className=\"py-2 flex flex-nowrap items-center border-bottom\" title={member.Name}>\n                                    <Avatar className=\"mr-2 shrink-0\">{getInitials(member.Name)}</Avatar>\n                                    <div>\n                                        <div className=\"text-ellipsis max-100\" title={member.Name}>\n                                            {member.Name}\n                                        </div>\n                                        <div className=\"max-w-full flex\">\n                                            <span className=\"flex-1 mr-2 text-ellipsis\">\n                                                {memberAddresses[0]?.Email}\n                                            </span>\n                                            {member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN && (\n                                                <span className=\"shrink-0\">\n                                                    <Badge type=\"light\">{c('Admin').t`admin`}</Badge>\n                                                </span>\n                                            )}\n                                        </div>\n                                    </div>\n                                </li>\n                            );\n                        })}\n                </ul>\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={handleClose} disabled={loading}>\n                    {c('Action').t`Cancel`}\n                </Button>\n                <Button loading={loading} type=\"submit\" color=\"norm\" disabled={loading}>\n                    {c('Action').t`Send reminder`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default SendEmailReminderTwoFAModal;\n","import { c } from 'ttag';\n\nimport { useMemberAddresses } from '@proton/account';\nimport { Button } from '@proton/atoms/Button';\nimport { Info, useConfig, useMembers, useModalState } from '@proton/components';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport { Label, Loader, Row } from '../../components';\nimport { SettingsParagraph } from '../account';\nimport SendEmailReminderTwoFAModal from './SendEmailReminderTwoFAModal';\n\ninterface Props {\n    organization?: Organization;\n}\n\nconst OrganizationTwoFARemindersSection = ({ organization }: Props) => {\n    const { APP_NAME } = useConfig();\n    const [modalProps, setModal, renderModal] = useModalState();\n    const [members] = useMembers();\n    const noTwoFAMembers =\n        members?.filter((member) => (member.State === undefined || member.State === 1) && member['2faStatus'] === 0) ||\n        [];\n\n    const { value: memberAddressesMap } = useMemberAddresses({ members, partial: true });\n\n    if (!organization || !members) {\n        return <Loader />;\n    }\n\n    return (\n        <>\n            {renderModal && (\n                <SendEmailReminderTwoFAModal\n                    {...modalProps}\n                    members={noTwoFAMembers}\n                    memberAddressesMap={memberAddressesMap}\n                />\n            )}\n            <SettingsParagraph\n                learnMoreUrl={\n                    APP_NAME === APPS.PROTONVPN_SETTINGS\n                        ? 'https://protonvpn.com/support/require-2fa-organization'\n                        : getKnowledgeBaseUrl('/two-factor-authentication-organization')\n                }\n            >\n                {c('Info').t`Send emails to encourage your members to protect their accounts with 2FA.`}\n            </SettingsParagraph>\n            <Row className=\"mt-1\">\n                <Label>\n                    <span className=\"mr-0.5\">{c('Label').t`Email`}</span>\n                    <span className=\"hidden md:inline\">\n                        <Info\n                            title={c('Tooltip')\n                                .t`Members who do not use 2FA will get an email asking them to enable it as soon as possible.`}\n                        />\n                    </span>\n                </Label>\n                <div className=\"flex items-center\">\n                    <Button\n                        id=\"send-email-reminder-button\"\n                        onClick={() => setModal(true)}\n                        disabled={noTwoFAMembers.length === 0}\n                    >{c('Action').t`Send email reminder`}</Button>\n                </div>\n            </Row>\n        </>\n    );\n};\n\nexport default OrganizationTwoFARemindersSection;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Info, useApi } from '@proton/components';\nimport { queryEnforceTwoFA, queryRemoveTwoFA } from '@proton/shared/lib/api/organization';\nimport { APPS, ORGANIZATION_TWOFA_SETTING } from '@proton/shared/lib/constants';\nimport { hasTwoFARequiredForAdminOnly, hasTwoFARequiredForAll } from '@proton/shared/lib/helpers/organization';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport { Loader, Toggle } from '../../components';\nimport { useConfig, useNotifications } from '../../hooks';\nimport { SettingsLayout, SettingsLayoutLeft, SettingsLayoutRight, SettingsParagraph } from '../account';\n\ninterface Props {\n    organization?: Organization;\n}\n\nconst OrganizationTwoFAEnforcementSection = ({ organization }: Props) => {\n    const api = useApi();\n    const { APP_NAME } = useConfig();\n\n    const [isTwoFARequiredForAdminOnlyChecked, setIsTwoFARequiredForAdminOnlyChecked] = useState(\n        hasTwoFARequiredForAdminOnly(organization)\n    );\n    const [isTwoFARequiredForAllChecked, setIsTwoFARequiredForAllChecked] = useState(\n        hasTwoFARequiredForAll(organization)\n    );\n    const { createNotification } = useNotifications();\n\n    if (!organization) {\n        return <Loader />;\n    }\n\n    const handleEnforceTwoFA = async (require: number) => {\n        await api(queryEnforceTwoFA(require));\n        if (require === ORGANIZATION_TWOFA_SETTING.REQUIRED_ADMIN_ONLY) {\n            setIsTwoFARequiredForAdminOnlyChecked(true);\n            setIsTwoFARequiredForAllChecked(false);\n            createNotification({\n                text: c('Notification').t`Two-factor authentication has been enforced for administrators`,\n            });\n            return;\n        }\n        setIsTwoFARequiredForAdminOnlyChecked(true);\n        setIsTwoFARequiredForAllChecked(true);\n        createNotification({\n            text: c('Notification').t`Two-factor authentication has been enforced for all members`,\n        });\n    };\n\n    const handleRemoveTwoFA = async () => {\n        await api(queryRemoveTwoFA());\n        setIsTwoFARequiredForAdminOnlyChecked(false);\n        setIsTwoFARequiredForAllChecked(false);\n        createNotification({\n            text: c('Notification').t`Two-factor authentication is not required anymore`,\n        });\n    };\n\n    return (\n        <>\n            <SettingsParagraph>\n                {c('Info')\n                    .t`We recommend notifying the organization members and asking them to set up 2FA for their accounts before enforcing the use of 2FA.`}\n            </SettingsParagraph>\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"two-fa-admin\" className=\"text-semibold\">\n                        <span className=\"mr-0.5\">{c('Label').t`Require 2FA for administrators`}</span>\n                        <Info\n                            url={\n                                APP_NAME === APPS.PROTONVPN_SETTINGS\n                                    ? 'https://protonvpn.com/support/require-2fa-organization'\n                                    : getKnowledgeBaseUrl('/two-factor-authentication-2fa')\n                            }\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight isToggleContainer>\n                    <Toggle\n                        id=\"two-fa-admin\"\n                        checked={isTwoFARequiredForAdminOnlyChecked || isTwoFARequiredForAllChecked}\n                        disabled={isTwoFARequiredForAllChecked}\n                        onChange={() =>\n                            !isTwoFARequiredForAdminOnlyChecked\n                                ? handleEnforceTwoFA(ORGANIZATION_TWOFA_SETTING.REQUIRED_ADMIN_ONLY)\n                                : handleRemoveTwoFA()\n                        }\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"two-fa-member\" className=\"text-semibold\">\n                        <span className=\"mr-0.5\">{c('Label').t`Require 2FA for everyone`}</span>\n                        <Info\n                            url={\n                                APP_NAME === APPS.PROTONVPN_SETTINGS\n                                    ? 'https://protonvpn.com/support/require-2fa-organization'\n                                    : getKnowledgeBaseUrl('/two-factor-authentication-2fa')\n                            }\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight isToggleContainer>\n                    <Toggle\n                        id=\"two-fa-member\"\n                        checked={isTwoFARequiredForAllChecked}\n                        onChange={() =>\n                            !isTwoFARequiredForAllChecked\n                                ? handleEnforceTwoFA(ORGANIZATION_TWOFA_SETTING.REQUIRED_ALL)\n                                : handleRemoveTwoFA()\n                        }\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n        </>\n    );\n};\n\nexport default OrganizationTwoFAEnforcementSection;\n","import { createHooks } from '@proton/redux-utilities';\n\nimport { samlSSOThunk, selectSamlSSO } from './index';\n\nconst hooks = createHooks(samlSSOThunk, selectSamlSSO);\n\nexport const useSamlSSO = hooks.useValue;\nexport const useGetSamlSSO = hooks.useGet;\n","import { c } from 'ttag';\n\nimport { Input } from '@proton/atoms/Input';\nimport { Copy, InputFieldTwo } from '@proton/components/components';\nimport { InputFieldProps } from '@proton/components/components/v2/field/InputField';\nimport { useNotifications } from '@proton/components/hooks';\nimport clsx from '@proton/utils/clsx';\n\ninterface Props extends Omit<InputFieldProps<typeof Input>, 'readonly' | 'unstyled'> {}\n\nconst ReadonlyFieldWithCopy = ({ value, inputContainerClassName, ...rest }: Props) => {\n    const { createNotification } = useNotifications();\n\n    const onCopy = () => {\n        createNotification({ text: c('Info').t`Copied to clipboard` });\n    };\n\n    return (\n        <InputFieldTwo\n            value={value}\n            readOnly\n            inputContainerClassName={clsx('w-full', inputContainerClassName)}\n            suffix={<Copy size=\"small\" shape=\"ghost\" color=\"weak\" value={`${value}`} 