s) {\n        return null;\n    }\n\n    const { text, className, iconName } = domainStateProperties;\n\n    return (\n        <>\n            {renderTXTRecordModal && <TXTRecordModal domain={domain} {...txtRecordModalProps} />}\n\n            <div className=\"flex gap-1 flex-nowrap\">\n                <Icon className={clsx('shrink-0', className)} type=\"warning\" name={iconName} />\n                <span>\n                    {text}{' '}\n                    <InlineLinkButton className=\"color-inherit\" onClick={() => showTXT()}>\n                        {c('Action').t`See DNS TXT record`}\n                    </InlineLinkButton>\n                </span>\n            </div>\n        </>\n    );\n};\n\nexport default DomainVerificationState;\n","import { useEffect } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport metrics, { observeApiError } from '@proton/metrics';\nimport { deleteDomain } from '@proton/shared/lib/api/domains';\nimport { Domain } from '@proton/shared/lib/interfaces';\n\nimport { Prompt, PromptProps } from '../../../components';\nimport { useApi, useEventManager, useNotifications } from '../../../hooks';\n\ninterface Props extends Omit<PromptProps, 'title' | 'buttons' | 'children'> {\n    domain: Domain;\n}\n\nconst RemoveSSODomain = ({ domain, ...rest }: Props) => {\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const { call } = useEventManager();\n    const [loading, withLoading] = useLoading();\n\n    useEffect(() => {\n        void metrics.core_sso_remove_domain_modal_load_total.increment({ step: 'remove-domain' });\n    }, []);\n\n    const handleConfirmDelete = async () => {\n        try {\n            await api(deleteDomain(domain.ID));\n            await call();\n            rest.onClose?.();\n            createNotification({ text: c('Success message').t`Domain deleted` });\n\n            metrics.core_sso_remove_domain_total.increment({\n                status: 'success',\n            });\n        } catch (error) {\n            observeApiError(error, (status) =>\n                metrics.core_sso_remove_domain_total.increment({\n                    status,\n                })\n            );\n            throw error;\n        }\n    };\n\n    const boldDomain = <b key=\"remove-sso-domain-name\">{domain.DomainName}</b>;\n\n    return (\n        <Prompt\n            title={c('Title').t`Remove domain`}\n            buttons={[\n                <Button\n                    color=\"danger\"\n                    onClick={() => {\n                        void withLoading(handleConfirmDelete());\n                    }}\n                    loading={loading}\n                >{c('Action').t`Remove`}</Button>,\n                <Button onClick={rest.onClose} disabled={loading}>{c('Action').t`Cancel`}</Button>,\n            ]}\n            {...rest}\n        >\n            <div>{c('Info').jt`Are you sure you want to remove the domain ${boldDomain}?`}</div>\n        </Prompt>\n    );\n};\n\nexport default RemoveSSODomain;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    useApi,\n    useEventManager,\n    useNotifications,\n} from '@proton/components';\nimport useLoading from '@proton/hooks/useLoading';\nimport { removeSAMLConfig } from '@proton/shared/lib/api/samlSSO';\nimport { SSO } from '@proton/shared/lib/interfaces';\nimport errorImg from '@proton/styles/assets/img/errors/error-generic-triangle.svg';\n\ninterface Props extends ModalProps {\n    sso: SSO;\n}\n\nconst RemoveSSOModal = ({ sso, onClose, ...rest }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const [loading, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n\n    const removeSSO = async () => {\n        await api(removeSAMLConfig(sso.ID));\n        await call();\n\n        createNotification({\n            text:\n                // translator: refers to removing the SSO configuration\n                c('Info').t`Single sign-on removed`,\n        });\n\n        onClose?.();\n    };\n\n    const boldSSOUserInformation = (\n        <b key=\"bold-sso-information\">\n            {\n                // translator: full sentence 'SSO users (provided by your Identity Provider) will be deleted and you will have to create them manually to add them back to your organization.'\n                c('Info').t`SSO users (provided by your Identity Provider) will be deleted`\n            }\n        </b>\n    );\n\n    return (\n        <ModalTwo onClose={onClose} size=\"small\" {...rest}>\n            <ModalTwoHeader title={c('Title').t`Remove single sign-on for your organization?`} />\n            <ModalTwoContent>\n                <div className=\"text-center my-8\">\n                    <img className=\"m-auto w-custom\" style={{ '--w-custom': '6rem' }} src={errorImg} alt=\"\" />\n                </div>\n                <p className=\"m-0 text-bold\">{c('Info')\n                    .t`The credentials from your Identity Provider will be deleted.`}</p>\n                <p className=\"my-4\">{c('Info').t`Once single sign-on is disabled for your organization:`}</p>\n                <ul className=\"mt-0\">\n                    <li>\n                        {\n                            // translator: full sentence 'SSO users (provided by your Identity Provider) will be deleted and you will have to create them manually to add them back to your organization.'\n                            c('Info')\n                                .jt`${boldSSOUserInformation} and you will have to create them manually to add them back to your organization`\n                        }\n                    </li>\n                    <li>\n                        {c('Info')\n                            .t`Non-SSO users (created manually, not provided by your Identity Provider) can still log in to your organization`}\n                    </li>\n                </ul>\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                <Button color=\"danger\" onClick={() => withLoading(removeSSO)} loading={loading}>\n                    {c('Action').t`Remove single sign-on`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default RemoveSSOModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms/Button';\nimport { Domain, SSO } from '@proton/shared/lib/interfaces';\n\nimport { useModalState } from '../../../components';\nimport { SettingsParagraph, SettingsSection } from '../../account';\nimport RemoveSSOModal from './RemoveSSOModal';\n\ninterface Props {\n    domain: Domain;\n    ssoConfig: SSO;\n}\n\nconst RemoveSSOSection = ({ domain, ssoConfig }: Props) => {\n    const [removeSSOModalProps, setRemoveSSOModalOpen, renderRemoveSSOModal] = useModalState();\n\n    const removeSSO = () => {\n        setRemoveSSOModalOpen(true);\n    };\n\n    const boldDomainName = <b key={domain.ID}>{domain.DomainName}</b>;\n\n    return (\n        <>\n            {renderRemoveSSOModal && <RemoveSSOModal sso={ssoConfig} {...removeSSOModalProps} />}\n            <SettingsSection>\n                <SettingsParagraph learnMoreUrl=\"https://protonvpn.com/support/sso\">\n                    {c('Info').jt`This will remove SSO for ${boldDomainName}.`}\n                </SettingsParagraph>\n\n                <Button color=\"danger\" onClick={removeSSO}>\n                    {c('Action').t`Stop using single sign-on`}\n                </Button>\n            </SettingsSection>\n        </>\n    );\n};\n\nexport default RemoveSSOSection;\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms/Button';\nimport useLoading from '@proton/hooks/useLoading';\nimport metrics, { observeApiError } from '@proton/metrics';\nimport { updateSAMLConfig } from '@proton/shared/lib/api/samlSSO';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { Domain, SSO } from '@proton/shared/lib/interfaces';\n\nimport { Info, InputFieldTwo, TextAreaTwo, useFormErrors } from '../../../components';\nimport { useApi, useEventManager, useNotifications } from '../../../hooks';\nimport { SettingsLayout, SettingsLayoutLeft, SettingsLayoutRight } from '../../account';\nimport { IdentityProviderEndpointsContentProps } from './IdentityProviderEndpointsContent';\nimport ReadonlyFieldWithCopy from './ReadonlyFieldWithCopy';\n\ninterface SSOInfo {\n    url: string;\n    entity: string;\n    certificate: string;\n}\n\ninterface Props extends IdentityProviderEndpointsContentProps {\n    domain: Domain;\n    sso: SSO;\n    onImportSamlClick: () => void;\n}\n\nconst SSOInfoForm = ({ domain, sso, issuerID, callbackURL, onImportSamlClick }: Props) => {\n    const { onFormSubmit, validator } = useFormErrors();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const api = useApi();\n\n    const ssoInfo: SSOInfo = {\n        url: sso.SSOURL,\n        entity: sso.SSOEntityID,\n        certificate: sso.Certificate,\n    };\n\n    const [ssoDiff, setSsoDiff] = useState<Partial<SSOInfo>>({});\n    const isFormDirty = Object.keys(ssoDiff).length;\n\n    const [submitting, withSubmitting] = useLoading();\n\n    const onChange = (key: keyof SSOInfo) => (value: string) => {\n        setSsoDiff((diff) => {\n            if (value === ssoInfo[key]) {\n                delete diff[key];\n                return { ...diff };\n            }\n            return {\n                ...diff,\n                [key]: value,\n            };\n        });\n    };\n\n    const url = ssoDiff.url ?? ssoInfo.url;\n    const entity = ssoDiff.entity ?? ssoInfo.entity;\n    const certificate = ssoDiff.certificate ?? ssoInfo.certificate;\n\n    useEffect(() => {\n        void metrics.core_sso_saml_info_page_load_total.increment({});\n    }, []);\n\n    const handleSubmit = async () => {\n        if (!onFormSubmit()) {\n            return;\n        }\n\n        try {\n            await api(\n                updateSAMLConfig(sso.ID, {\n                    DomainID: domain.ID,\n                    SSOURL: url,\n                    SSOEntityID: entity,\n                    Certificate: certificate,\n                })\n            );\n\n            await call();\n            setSsoDiff({});\n\n            createNotification({ text: c('Info').t`SAML configuration saved` });\n\n            metrics.core_sso_saml_update_info_total.increment({ status: 'success' });\n        } catch (error) {\n            observeApiError(error, (status) => {\n                metrics.core_sso_saml_update_info_total.increment({ status });\n            });\n        }\n    };\n\n    return (\n        <form\n            onSubmit={(e) => {\n                e.preventDefault();\n                void withSubmitting(handleSubmit());\n            }}\n        >\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"ssoUrl\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Single sign-on URL`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Endpoint URL from identity provider (e.g. https://idp.example.com/sso/saml)`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <InputFieldTwo\n                        id=\"ssoUrl\"\n                        value={url}\n                        onValue={onChange('url')}\n                        error={validator([requiredValidator(url)])}\n                        disableChange={submitting}\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"ssoEntity\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Single sign-on entity ID`}</span>\n                        <Info\n                            title={c('Tooltip').t`Usually an URL that contains the identity provider's name within`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <InputFieldTwo\n                        id=\"ssoEntity\"\n                        value={entity}\n                        onValue={onChange('entity')}\n                        error={validator([requiredValidator(entity)])}\n                        disableChange={submitting}\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"ssoCertificate\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Public certificate (X.509)`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Identity provider’s public key to sign authentication assertions. Get the certificate hash from your identity provider.`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <InputFieldTwo\n                        id=\"ssoCertificate\"\n                        as={TextAreaTwo}\n                        rows={12}\n                        value={certificate}\n                        onValue={onChange('certificate')}\n                        error={validator([requiredValidator(certificate)])}\n                        disableChange={submitting}\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"acsUrl\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Reply (ACS) URL`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Copy and paste this URL into the ACS (Assertion Consumer Service) URL field of your identity provider`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <ReadonlyFieldWithCopy id=\"acsUrl\" value={callbackURL} />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"acsUrl\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Issuer ID`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Copy and paste this URL into the entity ID field of your identity provider`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <ReadonlyFieldWithCopy id=\"acsUrl\" value={issuerID} />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <div className=\"flex gap-4\">\n                <Button onClick={onImportSamlClick}>{c('Action').t`Import new SAML metadata`}</Button>\n                <Button color=\"norm\" disabled={!isFormDirty} loading={submitting} type=\"submit\">\n                    {c('Action').t`Save SAML configuration`}\n                </Button>\n            </div>\n        </form>\n    );\n};\n\nexport default SSOInfoForm;\n","import { ReactNode, useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useApi, useEventManager } from '@proton/components/hooks';\nimport useLoading from '@proton/hooks/useLoading';\nimport metrics, { observeApiError } from '@proton/metrics/index';\nimport { addDomain } from '@proton/shared/lib/api/domains';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { Domain } from '@proton/shared/lib/interfaces';\n\nimport {\n    Form,\n    Icon,\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    useFormErrors,\n} from '../../../components';\nimport TXTSection from './TXTSection';\n\nenum STEP {\n    DOMAIN_INPUT,\n    TXT_RECORD,\n}\n\ninterface Props extends ModalProps {\n    onContinue: () => void;\n}\n\nconst SetupSSODomainModal = ({ onContinue, onClose, ...rest }: Props) => {\n    const [step, setStep] = useState(STEP.DOMAIN_INPUT);\n    const [domainName, setDomainName] = useState('');\n    const [domain, setDomain] = useState<Domain>();\n\n    useEffect(() => {\n        const stepLabel = (() => {\n            if (step === STEP.TXT_RECORD) {\n                return 'txt-record';\n            }\n\n            return 'domain-input';\n        })();\n\n        void metrics.core_sso_setup_domain_modal_load_total.increment({ step: stepLabel });\n    }, [step]);\n\n    const api = useApi();\n    const { call } = useEventManager();\n    const [submitting, withSubmitting] = useLoading();\n    const { validator, onFormSubmit } = useFormErrors();\n\n    const {\n        title,\n        content,\n        footer,\n        onSubmit,\n    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {\n        if (step === STEP.DOMAIN_INPUT) {\n            const handleSubmit = async () => {\n                if (!onFormSubmit()) {\n                    return;\n                }\n\n                try {\n                    const { Domain } = await api<{ Domain: Domain }>(\n                        addDomain({ Name: domainName, AllowedForMail: false, AllowedForSSO: true })\n                    );\n                    setDomain(Domain);\n\n                    await call();\n                    setStep(STEP.TXT_RECORD);\n                } catch (error) {\n                    observeApiError(error, (status) =>\n                        metrics.core_sso_setup_domain_total.increment({\n                            status,\n                        })\n                    );\n\n                    throw error;\n                }\n            };\n            return {\n                title: c('Info').t`Add domain`,\n                onSubmit: () => withSubmitting(handleSubmit),\n                content: (\n                    <>\n                        <div className=\"mb-6\">\n                            {c('Info').t`Specify the domain which is allowed to authenticate with SAML SSO.`}\n                        </div>\n                        <InputFieldTwo\n                            id=\"domain\"\n                            prefix={<Icon name=\"globe\" />}\n                            label={c('Label').t`Allowed domain`}\n                            placeholder={c('Label').t`e.g. example.com`}\n                            error={validator([requiredValidator(domainName)])}\n                            autoFocus\n                            disableChange={submitting}\n                            value={domainName}\n                            onValue={setDomainName}\n                        />\n                    </>\n                ),\n                footer: (\n                    <>\n                        <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                        <Button type=\"submit\" loading={submitting} color=\"norm\">\n                            {c('Action').t`Add domain`}\n                        </Button>\n                    </>\n                ),\n            };\n        }\n\n        if (step === STEP.TXT_RECORD && domain) {\n            return {\n                title: c('Info').t`Verify domain`,\n                content: <TXTSection domain={domain} />,\n                footer: (\n                    <>\n                        <Button onClick={onClose}>{c('Action').t`Close`}</Button>\n                        <Button onClick={onContinue} color=\"norm\">\n                            {c('Action').t`Continue`}\n                        </Button>\n                    </>\n                ),\n            };\n        }\n\n        throw new Error('No step found');\n    })();\n\n    return (\n        <Modal as={onSubmit ? Form : undefined} onSubmit={onSubmit} size=\"large\" onClose={onClose} {...rest}>\n            <ModalHeader title={title} />\n            <ModalContent>{content}</ModalContent>\n            <ModalFooter>{footer}</ModalFooter>\n        </Modal>\n    );\n};\n\nexport default SetupSSODomainModal;\n","import { ThunkAction, UnknownAction } from '@reduxjs/toolkit';\n\nimport type { ProtonThunkArguments } from '@proton/redux-shared-store';\nimport { setupSCIM as setupSCIMConfig, updateSCIM as updateSCIMConfig } from '@proton/shared/lib/api/samlSSO';\nimport { generateRandomBytes } from '@proton/shared/lib/helpers/crypto';\nimport { uint8ArrayToBase64String } from '@proton/shared/lib/helpers/encoding';\nimport type { Api } from '@proton/shared/lib/interfaces';\n\nimport { type SamlState, selectSamlSSO, updateScim } from './index';\n\nexport const disableSCIMAction = ({\n    api,\n}: {\n    api: Api;\n}): ThunkAction<Promise<void>, SamlState, ProtonThunkArguments, UnknownAction> => {\n    return async (dispatch) => {\n        await api(updateSCIMConfig({ State: 0 }));\n        dispatch(updateScim({ baseUrl: '', state: 0 }));\n    };\n};\n\nexport const setupSCIMAction = ({\n    type,\n    api,\n}: {\n    type: 'setup' | 'generated';\n    api: Api;\n}): ThunkAction<Promise<{ token: string; baseUrl: string }>, SamlState, ProtonThunkArguments, UnknownAction> => {\n    return async (dispatch, getState) => {\n        const token = generateRandomBytes(20);\n        const base64Token = uint8ArrayToBase64String(token);\n        const config =\n            type === 'setup'\n                ? setupSCIMConfig({ Password: base64Token })\n                : updateSCIMConfig({\n                      State: 1,\n                      Password: base64Token,\n                  });\n\n        const result = await api<{ SCIMBaseURL: string | undefined }>(config);\n\n        const scimInfo = selectSamlSSO(getState())?.value?.scimInfo;\n        const baseUrl = result?.SCIMBaseURL || scimInfo?.baseUrl || '';\n\n        dispatch(updateScim({ baseUrl, state: 1 }));\n\n        return {\n            token: base64Token,\n            baseUrl,\n        };\n    };\n};\n","import { CryptoProxy } from '@proton/crypto';\nimport { arrayToBinaryString, arrayToHexString, binaryStringToArray } from '@proton/crypto/lib/utils';\n\nimport { stringToUint8Array, uint8ArrayToBase64String, uint8ArrayToString } from './encoding';\n\nexport const getSHA256String = async (data: string) => {\n    const value = await CryptoProxy.computeHash({ algorithm: 'SHA256', data: binaryStringToArray(data) });\n    return arrayToHexString(value);\n};\n\nexport const getSHA256BinaryString = async (data: string) => {\n    const value = await CryptoProxy.computeHash({ algorithm: 'SHA256', data: binaryStringToArray(data) });\n    return arrayToBinaryString(value);\n};\n\nexport const getSHA256Base64String = async (data: string) => {\n    const value = await CryptoProxy.computeHash({ algorithm: 'SHA256', data: binaryStringToArray(data) });\n    return uint8ArrayToBase64String(value);\n};\n\nexport const generateRandomBytes = (numberOfBytes: number) => crypto.getRandomValues(new Uint8Array(numberOfBytes));\n\nexport const xorEncryptDecrypt = ({ key, data }: { key: string; data: string }) => {\n    if (key.length !== data.length) {\n        throw new Error('The length of the key and data do not match.');\n    }\n\n    const Uint8Key = stringToUint8Array(key);\n    const Uint8Data = stringToUint8Array(data);\n\n    const xored = new Uint8Array(Uint8Data.length);\n\n    for (let j = 0; j < Uint8Data.length; j++) {\n        xored[j] = +Uint8Key[j] ^ +Uint8Data[j];\n    }\n\n    return uint8ArrayToString(xored);\n};\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport useLoading from '@proton/hooks/useLoading';\nimport { BRAND_NAME } from '@proton/shared/lib/constants';\nimport noop from '@proton/utils/noop';\n\nimport { ModalProps, ModalTwo, ModalTwoContent, ModalTwoFooter, ModalTwoHeader } from '../../../../components';\nimport getBoldFormattedText from '../../../../helpers/getBoldFormattedText';\n\ninterface Props extends Omit<ModalProps, 'children' | 'title' | 'buttons'> {\n    onConfirm: () => Promise<void>;\n}\n\nconst DisableSCIMModal = ({ onClose, onConfirm, ...props }: Props) => {\n    const [loading, withLoading] = useLoading();\n\n    return (\n        <ModalTwo size=\"small\" {...props} onClose={onClose}>\n            <ModalTwoHeader title={c('scim: Title').t`Disable SCIM integration?`} {...props} />\n            <ModalTwoContent>\n                <p>\n                    <b>{c('scim: Info').t`The SCIM base URL and token will be deleted.`}</b>\n                </p>\n                <p>\n                    {getBoldFormattedText(\n                        c('scim: Info')\n                            .t`Once SCIM is disabled for your organization, **all SCIM users provided automatically by your identity provider will be converted to SSO users** and you will be able to manage them directly within the ${BRAND_NAME} settings.`\n                    )}\n                </p>\n                <p>\n                    {c('scim: Info')\n                        .t`To re-enable syncing with your identity provider, you need to complete the SCIM integration again.`}\n                </p>\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                <Button\n                    color=\"danger\"\n                    loading={loading}\n                    onClick={() => {\n                        withLoading(onConfirm()).catch(noop);\n                    }}\n                >\n                    {c('scim: Action').t`Disable SCIM`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default DisableSCIMModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport useLoading from '@proton/hooks/useLoading';\nimport noop from '@proton/utils/noop';\n\nimport { Prompt, PromptProps } from '../../../../components';\n\ninterface Props extends Omit<PromptProps, 'title' | 'buttons' | 'children'> {\n    onConfirm: () => Promise<void>;\n}\n\nconst RegenerateSCIMConfirmModal = ({ onConfirm, onClose, ...props }: Props) => {\n    const [loading, withLoading] = useLoading();\n    return (\n        <Prompt\n            onClose={onClose}\n            {...props}\n            title={c('scim: Title').t`Generate new SCIM token?`}\n            buttons={[\n                <Button\n                    color=\"danger\"\n                    onClick={() => {\n                        withLoading(onConfirm()).catch(noop);\n                    }}\n                    loading={loading}\n                >\n                    {c('scim: Action').t`Generate token`}\n                </Button>,\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n            ]}\n        >\n            <p>\n                {c('scim: Info')\n                    .t`The SCIM automatic provisioning will be disabled until you enter the new SCIM token into your identity provider’s settings.`}\n            </p>\n        </Prompt>\n    );\n};\n\nexport default RegenerateSCIMConfirmModal;\n","import { c } from 'ttag';\n\nimport { Button, Href } from '@proton/atoms';\nimport { VPN_APP_NAME } from '@proton/shared/lib/constants';\n\nimport {\n    Icon,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n} from '../../../../components';\nimport ReadonlyFieldWithCopy from '../ReadonlyFieldWithCopy';\n\nexport interface SCIMConfiguration {\n    baseUrl: string;\n    token: string;\n    type: 'setup' | 'generated' | 'static';\n}\n\ntype SetupSCIMModalProps = ModalProps & SCIMConfiguration;\n\nconst SetupSCIMModal = ({ onClose, token, type, baseUrl, ...rest }: SetupSCIMModalProps) => {\n    return (\n        <Modal size=\"large\" onClose={onClose} {...rest}>\n            <ModalHeader\n                title={\n                    type === 'setup'\n                        ? c('scim: Info').t`Enter URL and token into your identity provider`\n                        : c('scim: Info').t`Enter token into your identity provider`\n                }\n            />\n            <ModalContent>\n                <div className=\"mb-6\">\n                    {type === 'setup'\n                        ? c('scim: Info')\n                              .t`Go to your identity provider, copy and paste the data below and finish configuring SCIM for ${VPN_APP_NAME}.`\n                        : c('scim: Info')\n                              .t`Go to your identity provider, copy and paste the token below and re-enable SCIM for ${VPN_APP_NAME}.`}\n                    <br />\n                    <Href href=\"https://protonvpn.com/support/sso\">{c('Info').t`Learn more`}</Href>\n                </div>\n                {type === 'setup' &